<?php
require_once __DIR__.'/_common.php';
$rows=sponsor_rows($conn,"SELECT pl.placement_reference,pl.status,pl.start_date,pl.end_date,pl.department,pl.location,pr.name programme_name,co.name cohort_name FROM placements pl LEFT JOIN programmes pr ON pr.id=pl.programme_id LEFT JOIN cohorts co ON co.id=pl.cohort_id ORDER BY pl.created_at DESC");
$counts=[];foreach(['pending_placement','placement_in_progress','placed','active','completed','withdrawn','cancelled'] as $status)$counts[$status]=sponsor_count($conn,"SELECT COUNT(*) total FROM placements WHERE status='".$conn->real_escape_string($status)."'");
sponsor_header('Placement outcomes','placements','Review recorded placement progress and completion status without exposing candidate contact details.'); ?>
<section class="sp-stats"><?php foreach([['All placements',array_sum($counts),'All statuses'],['In progress',$counts['placement_in_progress']+$counts['placed']+$counts['active'],'Placed / active / in progress'],['Completed',$counts['completed'],'Explicitly completed'],['Pending',$counts['pending_placement'],'Awaiting placement']] as $x): ?><article class="sp-stat"><div class="sp-stat-top"><?= sponsor_e($x[0]) ?><span class="sp-glyph">↗</span></div><strong><?= number_format((int)$x[1]) ?></strong><small><?= sponsor_e($x[2]) ?></small></article><?php endforeach; ?></section>
<div class="sp-card"><div class="sp-toolbar"><input class="sp-search" data-search="#placementTable" placeholder="Search reference, programme, cohort or status…" aria-label="Search placements"><select class="sp-select" data-filter-status><option value="">All statuses</option><?php foreach(array_keys($counts) as $s): ?><option value="<?= $s ?>"><?= sponsor_e(sponsor_status($s)) ?></option><?php endforeach; ?></select><a class="sp-btn" href="<?= url('sponsor/export.php?dataset=placements') ?>">↓ Export CSV</a></div><div class="sp-tablewrap"><table id="placementTable"><thead><tr><th>Reference</th><th>Programme</th><th>Cohort</th><th>Status</th><th>Department</th><th>Location</th><th>Start</th><th>End</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr data-status-row="<?= sponsor_e($r['status']) ?>"><td><strong><?= sponsor_e($r['placement_reference']) ?></strong></td><td><?= sponsor_e($r['programme_name']??'—') ?></td><td><?= sponsor_e($r['cohort_name']??'—') ?></td><td><span class="sp-pill <?= sponsor_e($r['status']) ?>"><?= sponsor_e(sponsor_status((string)$r['status'])) ?></span></td><td><?= sponsor_e($r['department']?:'—') ?></td><td><?= sponsor_e($r['location']?:'—') ?></td><td><?= sponsor_e(sponsor_date($r['start_date'])) ?></td><td><?= sponsor_e(sponsor_date($r['end_date'])) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="8" class="sp-empty">No placement records found.</td></tr><?php endif; ?></tbody></table></div></div><p class="sp-footnote">Placement status is taken from the placement register. It should not be interpreted as independently verified employment or long-term retention.</p><?php sponsor_footer(); ?>
